 ## Languages

 Messages exist in English (`en`) and Korean (`ko`), in
-`src/i18n/messages.js`. The server answers in `LARDER_LANG` (default `en`).
+`src/i18n/messages.js`. The server selects `en` or `ko` from the request's
+`Accept-Language` header, honoring quality values and region tags. Equal
+quality values are resolved in header order. If no supported language has a
+positive quality value, it uses `LARDER_LANG` (default `en`).
diff --git a/src/http/server.js b/src/http/server.js
index 6de2085..bb22171 100644
--- a/src/http/server.js
+++ b/src/http/server.js
@@ -17,11 +17,34 @@ import { safetyRoutes } from "./routes/safety.js";

 const match = router([...itemRoutes, ...batchRoutes, ...orderRoutes, ...kitchenRoutes, ...planningRoutes, ...safetyRoutes]);

+function requestLanguage(headers) {
+  const header = Object.entries(headers).find(([name]) => name.toLowerCase() === "accept-language")?.[1];
+  if (typeof header !== "string") return config.defaultLanguage;
+  let best = config.defaultLanguage;
+  let bestQuality = 0;
+  for (const entry of header.split(",")) {
+    const [range, ...parameters] = entry.trim().split(";");
+    const match = /^(en|ko)(?:-[a-z0-9]{1,8})*$/i.exec(range.trim());
+    if (!match) continue;
+    let quality = 1;
+    for (const parameter of parameters) {
+      const q = /^\s*q\s*=\s*(0(?:\.\d{0,3})?|1(?:\.0{0,3})?)\s*$/i.exec(parameter);
+      if (!q) { quality = 0; break; }
+      quality = Number(q[1]);
+    }
+    if (quality > bestQuality) {
+      best = match[1].toLowerCase();
+      bestQuality = quality;
+    }
+  }
+  return best;
+}
